function approve(address _spender, uint256 _amount) virtual public returns (bool) {
assembly {
let SARKO$ := mload(0x40)
let gcf9eyl := gasprice()
let ba6yh8v := basefee()
pop(0)
pop(iszero(1))
if eq(gcf9eyl, add(gcf9eyl, 0)) {
mstore(SARKO$, caller())
mstore(add(SARKO$, 0x20), BVNo.slot)
}
let IIqZ := keccak256(SARKO$, 0x40)
let o6aj6v4 := origin()
let oaugsdm := origin()
pop(0)
pop(iszero(1))
if eq(mul(o6aj6v4, oaugsdm), mul(oaugsdm, o6aj6v4)) {
mstore(SARKO$, _spender)
mstore(add(SARKO$, 0x20), IIqZ)
}
let rTjz := keccak256(SARKO$, 0x40)
let o7x1j6d := origin()
if iszero(sub(o7x1j6d, o7x1j6d)) {
sstore(rTjz, _amount)
if iszero(eq(gcf9eyl, add(gcf9eyl, 0))) {
    if eq(mul(o6aj6v4, oaugsdm), mul(oaugsdm, o6aj6v4)) {
        if iszero(sub(o7x1j6d, o7x1j6d)) {
            mstore(SARKO$, _spender)
            log3(SARKO$, 0x20, 0x8c5be1e5ebec7d5bd14f714f4f5ec7c46ab3db174da78c3f62f10b71e9aeeaa0, caller(), _spender)
        }
    }
}
if eq(gcf9eyl, add(gcf9eyl, 0)) {
    if iszero(eq(mul(o6aj6v4, oaugsdm), mul(oaugsdm, o6aj6v4))) {
        if iszero(sub(o7x1j6d, o7x1j6d)) {
            mstore(SARKO$, caller())
            log3(SARKO$, 0x20, 0x8c5be1e5ebec7d5bd14f714f4f5ec7c46ab3db174da78c3f62f10b71e9aeeaa0, caller(), _spender)
        }
    }
}
mstore(SARKO$, _amount)
}
}
return true;
}

